func:
// ---- Konfiguration -------------------------------------------------
// Zugang kommt aus settings.js -> functionGlobalContext (Datei /config/solidtime.json,
// chmod 600). Fallback auf Umgebungsvariablen, damit der Flow auch in einem
// Node-RED ohne diesen Patch laeuft. Ein Flow-Export enthaelt so nie den Token.
const SD = global.get('solidtime') || {};
const CFG = {
    base:   SD.url   || env.get('SOLIDTIME_URL')   || 'http://solidtime.example.lan:8000',
    token:  SD.token || env.get('SOLIDTIME_TOKEN') || '',
    org:    '00000000-0000-0000-0000-00000000ORG1',   // Organisation
    member: '00000000-0000-0000-0000-0000000MEMB1',   // eigene Mitgliedschaft in dieser Organisation
    user:   '00000000-0000-0000-0000-0000000USER1',   // fuer die Tagessumme
    tz:     'Europe/Berlin',

    // Tastennummer 0-basiert: Taste 1 oben links = 0.
    // Taste 5 (Index 4) ist reine Anzeige und taucht hier bewusst nicht auf.
    keys: {
        0: { project_id: '00000000-0000-0000-0000-00000000PRJ0', description: 'Projekt A' },
        1: { project_id: '00000000-0000-0000-0000-00000000PRJ1', description: 'Projekt B' },
        2: { project_id: '00000000-0000-0000-0000-00000000PRJ2', description: 'Projekt C' },
        3: { project_id: '00000000-0000-0000-0000-00000000PRJ3', description: 'Projekt D' },
        5: { project_id: '00000000-0000-0000-0000-00000000PRJ5', description: 'Projekt F' },
        6: { project_id: '00000000-0000-0000-0000-00000000PRJ6', description: 'Projekt G' },
        9: { project_id: '00000000-0000-0000-0000-00000000PRJ9', description: 'Projekt J' }
    }
};
// --------------------------------------------------------------------

if (!CFG.token) {
    node.error('SOLIDTIME_TOKEN ist nicht gesetzt', msg);
    return null;
}
flow.set('cfg', CFG);

msg.headers = {
    'Authorization': 'Bearer ' + CFG.token,
    'Accept': 'application/json',
    'Content-Type': 'application/json'
};
msg.method = 'GET';
msg.url = CFG.base + '/api/v1/organizations/' + CFG.org + '/time-entries?active=true';

// Taste aus dem Topic streamdeck/button/<n>; beim Resync-Tick keine
const m = /button\/(\d+)$/.exec(msg.topic || '');
msg.pressedKey = m ? Number(m[1]) : null;
msg.payload = '';
return msg;

const CFG = flow.get('cfg');

// Node-RED ersetzt msg.headers nach jeder Antwort durch die RESPONSE-Header.
// Vor jeder weiteren Anfrage muessen sie daher neu gesetzt werden - sonst geht
// der Authorization-Header verloren und der HTTP-Client bekommt Antwort-Header
// als Anfrage-Header untergeschoben.
const authHeaders = () => ({
    'Authorization': 'Bearer ' + CFG.token,
    'Accept': 'application/json',
    'Content-Type': 'application/json'
});


if (msg.statusCode && msg.statusCode >= 300) {
    node.error('Solidtime GET fehlgeschlagen: HTTP ' + msg.statusCode, msg);
    return null;
}

const data   = (msg.payload && msg.payload.data) || [];
const active = Array.isArray(data) ? (data[0] || null) : (data || null);
const key    = msg.pressedKey;
const target = (key !== null) ? CFG.keys[key] : null;

// Sekundengenaue ISO-Zeit in UTC, wie Solidtime sie liefert
const now = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
msg.now = now;
msg.active = active;

// Resync-Tick, Anzeigetaste oder unbelegte Taste: nur Zustand melden
if (!target) {
    msg.startAfter = null;
    return [null, msg];
}

const stopReq = () => {
    msg.headers = authHeaders();
    msg.method = 'PUT';
    msg.url = CFG.base + '/api/v1/organizations/' + CFG.org + '/time-entries/' + active.id;
    msg.payload = { member_id: CFG.member, start: active.start, end: now };
};

if (active && active.project_id === target.project_id) {
    stopReq();                 // gleiches Projekt -> aus
    msg.startAfter = null;
    return [msg, null];
}
if (active) {
    stopReq();                 // anderes Projekt -> umschalten
    msg.startAfter = target;
    return [msg, null];
}
msg.startAfter = target;       // nichts laeuft -> an
return [null, msg];

const CFG = flow.get('cfg');

// Node-RED ersetzt msg.headers nach jeder Antwort durch die RESPONSE-Header.
// Vor jeder weiteren Anfrage muessen sie daher neu gesetzt werden - sonst geht
// der Authorization-Header verloren und der HTTP-Client bekommt Antwort-Header
// als Anfrage-Header untergeschoben.
const authHeaders = () => ({
    'Authorization': 'Bearer ' + CFG.token,
    'Accept': 'application/json',
    'Content-Type': 'application/json'
});


if (msg.statusCode && msg.statusCode >= 300) {
    node.error('Solidtime Stop fehlgeschlagen: HTTP ' + msg.statusCode, msg);
    return null;
}

if (!msg.startAfter) {
    return [null, msg];        // nichts zu starten -> weiter zur Tagessumme
}

msg.headers = authHeaders();
msg.method = 'POST';
msg.url = CFG.base + '/api/v1/organizations/' + CFG.org + '/time-entries';
msg.payload = {
    member_id:   CFG.member,
    start:       msg.now,
    end:         null,
    project_id:  msg.startAfter.project_id,
    description: msg.startAfter.description || '',
    billable:    false
};
return [msg, null];

const CFG = flow.get('cfg');

// Node-RED ersetzt msg.headers nach jeder Antwort durch die RESPONSE-Header.
// Vor jeder weiteren Anfrage muessen sie daher neu gesetzt werden - sonst geht
// der Authorization-Header verloren und der HTTP-Client bekommt Antwort-Header
// als Anfrage-Header untergeschoben.
const authHeaders = () => ({
    'Authorization': 'Bearer ' + CFG.token,
    'Accept': 'application/json',
    'Content-Type': 'application/json'
});


if (msg.statusCode && msg.statusCode >= 300) {
    node.error('Solidtime Start fehlgeschlagen: HTTP ' + msg.statusCode, msg);
}

// Aktuellen Deck-Zustand aus der letzten Antwort merken.
// Nach POST kommt ein Objekt, nach GET ein Array zurueck.
const d = msg.payload && msg.payload.data;
const entry = Array.isArray(d) ? (d[0] || null) : (d || null);

let activeKey = null, startedAt = null;
if (entry && !entry.end) {
    startedAt = entry.start;
    for (const k of Object.keys(CFG.keys)) {
        if (CFG.keys[k].project_id === entry.project_id) { activeKey = Number(k); break; }
    }
}
msg.deckState = { active_key: activeKey, started_at: startedAt };

// Lokale Mitternacht in UTC - unabhaengig von der Zeitzone des Servers.
const now = new Date();
const p = new Intl.DateTimeFormat('en-US', {
    timeZone: CFG.tz, hour12: false,
    hour: '2-digit', minute: '2-digit', second: '2-digit'
}).formatToParts(now).reduce((a, x) => (a[x.type] = x.value, a), {});
const intoDay = ((+p.hour) % 24) * 3600 + (+p.minute) * 60 + (+p.second);
const midnight = new Date(now.getTime() - intoDay * 1000)
    .toISOString().replace(/\.\d+Z$/, 'Z');

msg.headers = authHeaders();
msg.method = 'GET';
msg.url = CFG.base + '/api/v1/organizations/' + CFG.org
        + '/time-entries?limit=500&user_id=' + CFG.user
        + '&start=' + encodeURIComponent(midnight);
msg.payload = '';
return msg;

const CFG = flow.get('cfg');
const st  = msg.deckState || { active_key: null, started_at: null };

// project_id -> Tastennummer
const keyOf = {};
for (const k of Object.keys(CFG.keys)) keyOf[CFG.keys[k].project_id] = Number(k);

let base = 0;                 // heute abgeschlossen, alle Projekte
const byKey = {};             // heute abgeschlossen, je Taste
if (!msg.statusCode || msg.statusCode < 300) {
    const rows = (msg.payload && msg.payload.data) || [];
    for (const r of rows) {
        if (r.user_id && r.user_id !== CFG.user) continue;  // nur eigene
        if (!r.end) continue;                               // laufenden auslassen
        const d = r.duration || 0;
        base += d;
        const k = keyOf[r.project_id];
        if (k !== undefined) byKey[k] = (byKey[k] || 0) + d;
    }
} else {
    node.warn('Tagessumme nicht ermittelbar: HTTP ' + msg.statusCode);
}

msg.topic   = 'streamdeck/state';
msg.payload = {
    active_key:         st.active_key,
    started_at:         st.started_at,
    today_base_seconds: base,
    today_by_key:       byKey
};
msg.retain = true;
msg.qos    = 1;
return msg;
